import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "./SellHouseForm.css";

export default function SellHouseForm() {
  const [form, setForm] = useState({
    title: "",
    description: "",
    area: "",
    bedrooms: "",
    bathrooms: "",
    price: "",
    address: "",
    owner: "",
    contact: "",
  });
  const [images, setImages] = useState([]);
  const [error, setError] = useState("");
  const navigate = useNavigate();

  const handleInput = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleImages = (e) => {
    const files = Array.from(e.target.files);
    if (files.length < 1 || files.length > 3) {
      setError("Please upload 1 to 3 images.");
      return;
    }
    setImages(files);
    setError("");
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (images.length < 1 || images.length > 3) {
      setError("Please upload 1 to 3 images.");
      return;
    }
    const data = new FormData();
    for (const key in form) data.append(key, form[key]);
    images.forEach(img => data.append("images", img));

    const res = await fetch(`${process.env.REACT_APP_BACKEND_URL}/sell/house`, {
      method: "POST",
      body: data,
    });
    if (res.ok) {
      setError("");
      alert("Your property has been listed!");
      navigate("/");
    } else {
      setError("Failed to submit.");
    }
  };

  return (
    <div className="sell-form-container">
      <h2>Sell Your House</h2>
      <form onSubmit={handleSubmit} encType="multipart/form-data">
        <input name="title" placeholder="Title" value={form.title} onChange={handleInput} required />
        <textarea name="description" placeholder="Description" value={form.description} onChange={handleInput} required />
        <input name="area" placeholder="Area (sqft)" type="number" value={form.area} onChange={handleInput} required />
        <input name="bedrooms" placeholder="Bedrooms" type="number" value={form.bedrooms} onChange={handleInput} required />
        <input name="bathrooms" placeholder="Bathrooms" type="number" value={form.bathrooms} onChange={handleInput} required />
        <input name="price" placeholder="Price (Rs)" type="number" value={form.price} onChange={handleInput} required />
        <input name="address" placeholder="Full Address" value={form.address} onChange={handleInput} required />
        <input name="owner" placeholder="Owner Name" value={form.owner} onChange={handleInput} required />
        <input name="contact" placeholder="Contact" value={form.contact} onChange={handleInput} required />
        <input type="file" accept="image/*" multiple onChange={handleImages} required />
        <small>(Upload 1-3 property images)</small>
        {error && <div className="error-msg">{error}</div>}
        <button type="submit">Submit</button>
      </form>
    </div>
  );
}
